     1	import type { StorageChange } from '../../../../domain/core/storage/storageService';
     2	import { canvasViewChanges, documentPrefix, historyChanges, type WorkspaceIndex } from '../../../../domain/mapping/workspace/workspaceRecords';
     3	import type { CanvasTransfer } from '../../../../domain/core/diagrams/canvasTransfer';
     4	import type { StoredCanvasSnapshot } from '../../../../domain/core/diagrams/canvasHistory';
     5	import { isCheckpointDelta } from '../../../../domain/core/diagrams/canvasCheckpointRecords';
     6	import type { CanvasDraft, CanvasWorkspace } from './canvasWorkspace';
     7	import type { CanvasSession } from './canvasSession';
     8	import type { SourcePaneViewState } from '../source-pane/sourcePaneViewState';
     9	import type { RecordStorage } from './recordStorage';
    10	
    11	/** Owns the translation from live owners to persisted records, never a global snapshot. */
    12	export class WorkspacePersistence {
    13	  private cursors = new WeakMap<CanvasSession, number>();
    14	  private known = new Map<string, CanvasDraft>();
    15	  private subscriptions: (() => void)[] = [];
    16	  private activeDocumentId?: string;
    17	  private transfers: CanvasTransfer[] = [];
    18	  private paused = false;
    19	  constructor(private readonly workspace: CanvasWorkspace, private readonly storage: RecordStorage,
    20	    private readonly projectId: string, private readonly view: SourcePaneViewState) {
    21	    const index = storage.get<WorkspaceIndex>('workspace');
    22	    this.activeDocumentId = index?.activeDocumentId; this.transfers = index?.transfers ?? [];
    23	    this.subscriptions.push(workspace.onPersist(ids => this.sync(ids)), view.subscribe(id => this.syncView(id)));
    24	    this.sync([...new Set([...(index?.documentIds ?? []), ...Object.keys(workspace.store.getState().drafts)])]);
    25	  }
    26	  setPaused(paused: boolean) { this.paused = paused; }
    27	  update(activeDocumentId: string | undefined, transfers: CanvasTransfer[]) {
    28	    this.activeDocumentId = activeDocumentId; this.transfers = transfers;
    29	    if (!this.paused) this.storage.batch([this.index()]);
    30	  }
    31	  private index(): StorageChange {
    32	    const ids = Object.keys(this.workspace.store.getState().drafts);
    33	    return { key: 'workspace', value: { projectId: this.projectId, documentIds: ids,
    34	      activeDocumentId: this.activeDocumentId && ids.includes(this.activeDocumentId) ? this.activeDocumentId : ids[0], transfers: this.transfers } satisfies WorkspaceIndex };
    35	  }
    36	  sync(ids = [...new Set([...this.known.keys(), ...Object.keys(this.workspace.store.getState().drafts)])]) {
    37	    if (this.paused) return;
    38	    const drafts = this.workspace.store.getState().drafts, changes: StorageChange[] = [];
    39	    for (const id of ids) {
    40	      const draft = drafts[id], prior = this.known.get(id), prefix = documentPrefix(id);
    41	      if (!draft) {
    42	        for (const key of this.storage.keys()) if (key.startsWith(prefix)) changes.push({ key, delete: true });
    43	        this.known.delete(id); continue;
    44	      }
    45	      const { representationId: savedRepresentationId, name, hidden, repositoryId, type, savedName, savedScene, savedEdges, revisionId } = draft;
    46	      changes.push({ key: prefix + 'metadata', value: { representationId: id, savedRepresentationId, repositoryId, type, name, hidden, version: draft.session.controller.getSnapshot().version } },
    47	        { key: prefix + 'baseline', value: { savedName, savedScene, savedEdges, revisionId } });
    48	      const cursor = this.cursors.get(draft.session), delta = draft.session.controller.persistenceChanges(cursor);
    49	      if (cursor === undefined) {
    50	        // Import/reset can replace a canvas's history graph under the same ID.
    51	        // Remove the old graph in the same atomic batch as its replacement.
    52	        const retained = new Set(historyChanges(id, delta).map(change => change.key));
    53	        for (const key of this.storage.keys()) {
    54	          if ((key.startsWith(prefix + 'revision/') || key.startsWith(prefix + 'checkpoint/')) && !retained.has(key)) changes.push({ key, delete: true });
    55	        }
    56	      }
    57	      for (const change of historyChanges(id, delta)) {
    58	        // A new runtime session may attach to history already present in storage.
    59	        // Revision IDs are immutable; checkpoints may have retired transfer links.
    60	        if (cursor === undefined && 'value' in change && this.storage.get(change.key)) {
    61	          if (change.key.startsWith(prefix + 'revision/')) continue;
    62	          const previous = this.storage.get<StoredCanvasSnapshot>(change.key);
    63	          if (change.key.startsWith(prefix + 'checkpoint/') && isCheckpointDelta(previous)
    64	            && JSON.stringify(previous) === JSON.stringify(change.value)) continue;
    65	        }
    66	        changes.push(change);
    67	      }
    68	      this.cursors.set(draft.session, delta.sequence);
    69	      const canvas = draft.session.controller.getSnapshot().canvas;
    70	      changes.push(...canvasViewChanges(id, { ...canvas, display: this.view.captureDisplay(id, canvas.display) }));
    71	      if (prior?.viewport !== draft.viewport || !prior) {
    72	        const viewport = this.view.captureCamera(id, draft.viewport);
    73	        if (viewport) changes.push({ key: prefix + 'viewport', value: viewport });
    74	      }
    75	      this.known.set(id, draft);
    76	    }
    77	    changes.push(this.index()); this.submit(changes);
    78	  }
    79	  private syncView(id: string) {
    80	    if (this.paused) return;
    81	    const draft = this.workspace.store.getState().drafts[id]; if (!draft) return;
    82	    const prefix = documentPrefix(id), canvas = draft.session.controller.getSnapshot().canvas;
    83	    const viewport = this.view.captureCamera(id, draft.viewport);
    84	    this.submit([...canvasViewChanges(id, { ...canvas, display: this.view.captureDisplay(id, canvas.display) }),
    85	      ...(viewport ? [{ key: prefix + 'viewport', value: viewport }] : [])]);
    86	  }
    87	  private submit(changes: StorageChange[]) {
    88	    // Content-addressed items are immutable and may be shared by view and history.
    89	    // Sending them once avoids retransmitting unchanged panels on every gesture.
    90	    const unique = new Map(changes.map(change => [change.key, change]));
    91	    this.storage.batch([...unique.values()].filter(change => !change.key.includes('/item/') || 'delete' in change || !this.storage.get(change.key)));
    92	  }
    93	  dispose() { this.subscriptions.forEach(off => off()); }
    94	}
