     1	import type { StorageChange } from '../../../../domain/core/storage/storageService';
     2	import type { MappingDocumentSnapshot, MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
     3	import { documentRecords, documentPrefix, type WorkspaceIndex, type WorkspaceRecordState } from '../../../../domain/mapping/workspace/workspaceRecords';
     4	import { RecordStorage } from './recordStorage';
     5	
     6	/** One worker per opened workspace; no worker construction in a store() call. */
     7	export class WorkspaceStorage {
     8	  records?: RecordStorage;
     9	  private worker?: Worker;
    10	  private id = 0;
    11	  private requests = new Map<number, { resolve(value: unknown): void; reject(error: Error): void }>();
    12	  private endpoint = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/workspace/records`;
    13	  private ready?: Promise<MappingWorkspaceSnapshot | null>;
    14	  private ensureWorker() {
    15	    if (this.worker) return this.worker;
    16	    const worker = this.worker = new Worker(new URL('./workspaceStorage.worker.ts', import.meta.url), { type: 'module' });
    17	    worker.onmessage = ({ data }) => {
    18	      const request = this.requests.get(data.id); if (!request) return;
    19	      this.requests.delete(data.id);
    20	      if (data.error) request.reject(Error(data.error)); else request.resolve(data.result);
    21	    };
    22	    const fail = () => {
    23	      this.requests.forEach(r => r.reject(Error('Workspace worker stopped; reload to reconnect'))); this.requests.clear();
    24	      worker.terminate(); this.worker = undefined;
    25	    };
    26	    worker.onerror = fail; worker.onmessageerror = fail;
    27	    return worker;
    28	  }
    29	  private request<T>(input: Record<string, unknown>): Promise<T> {
    30	    return new Promise((resolve, reject) => {
    31	      const id = ++this.id;
    32	      this.requests.set(id, { resolve: value => resolve(value as T), reject });
    33	      try { this.ensureWorker().postMessage({ ...input, id, endpoint: new URL(this.endpoint, location.href).href }); }
    34	      catch (e) { this.requests.delete(id); reject(e); }
    35	    });
    36	  }
    37	  load() {
    38	    return this.ready ??= this.request<{ state: WorkspaceRecordState; workspace: MappingWorkspaceSnapshot | null }>({ type: 'load' }).then(({ state, workspace }) => {
    39	      this.records = new RecordStorage(state, { write: batch => this.request({ type: 'write', batch }) }); return workspace;
    40	    }).catch(error => { this.ready = undefined; throw error; });
    41	  }
    42	  async project(snapshot: MappingWorkspaceSnapshot) { return this.request<StorageChange[]>({ type: 'project', snapshot }); }
    43	  async save(snapshot: MappingWorkspaceSnapshot) {
    44	    await this.load(); await this.records!.flush();
    45	    const changes = await this.project(snapshot);
    46	    await this.records!.commit(changes);
